def countSteadyWindows(nums, k, d):
    from collections import deque
    mx = deque()
    mn = deque()
    count = 0
    for i, x in enumerate(nums):
        while mx and nums[mx[-1]] <= x:
            mx.pop()
        mx.append(i)
        while mn and nums[mn[-1]] >= x:
            mn.pop()
        mn.append(i)
        if mx[0] <= i - k:
            mx.popleft()
        if mn[0] <= i - k:
            mn.popleft()
        if i >= k - 1 and nums[mx[0]] - nums[mn[0]] <= d:
            count += 1
    return count
